from collections import Counter
def analyze(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    cells={(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg}
    bars=[]; barcells=set()
    # vertical strips
    used=set()
    for c in range(w):
        r=0
        while r<h:
            if (r,c) in cells:
                r0=r
                while r<h and (r,c) in cells: r+=1
                if r-r0>=2:
                    col=g[r0][c]
                    if all(g[i][c]==col for i in range(r0,r)):
                        bars.append(dict(orient='V',fixed=c,span=(r0,r-1),color=col)); 
                        for i in range(r0,r): barcells.add((i,c))
            else: r+=1
    for r in range(h):
        c=0
        while c<w:
            if (r,c) in cells and (r,c) not in barcells:
                c0=c
                while c<w and (r,c) in cells and (r,c) not in barcells: c+=1
                if c-c0>=2:
                    col=g[r][c0]
                    if all(g[r][j]==col for j in range(c0,c)):
                        bars.append(dict(orient='H',fixed=r,span=(c0,c-1),color=col))
                        for j in range(c0,c): barcells.add((r,j))
            else: c+=1
    markers=[(r,c,g[r][c]) for (r,c) in cells-barcells]
    return bg,bars,markers

