            # direction: toward marker's perpendicular position
            for mm in markers:
                perp = mm[1] if b['orient']=='V' else mm[0]
                fixed = b['fixed']
                if perp!=fixed: break
            perp = m[1] if b['orient']=='V' else m[0]
