lib_code = '''"""Reusable ARC grid-transformation helpers."""
from collections import Counter


def background_color(grid):
    """Most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def find_structures(grid):
    """Split non-background cells into straight bars and isolated markers.

    Returns (bg, bars, markers) where bars are dicts with keys
    orient ('V' or 'H'), fixed (perpendicular coordinate), span ((lo, hi)
    along the bar axis) and color; markers are (row, col, color) tuples.
    """
    bg = background_color(grid)
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    bars, barcells = [], set()

    def add_bar(cells_run, orient, fixed, lo, hi):
        color = grid[cells_run[0][0]][cells_run[0][1]]
        if len(cells_run) >= 2 and all(grid[r][c] == color for r, c in cells_run):
            bars.append(dict(orient=orient, fixed=fixed, span=(lo, hi), color=color))
            barcells.update(cells_run)

    for c in range(w):
        r = 0
        while r < h:
            if (r, c) in cells:
                r0 = r
                while r < h and (r, c) in cells:
                    r += 1
                add_bar([(i, c) for i in range(r0, r)], 'V', c, r0, r - 1)
            else:
                r += 1
    for r in range(h):
        c = 0
        while c < w:
            if (r, c) in cells and (r, c) not in barcells:
                c0 = c
                while c < w and (r, c) in cells and (r, c) not in barcells:
                    c += 1
                add_bar([(r, j) for j in range(c0, c)], 'H', r, c0, c - 1)
            else:
                c += 1
    markers = [(r, c, grid[r][c]) for (r, c) in cells - barcells]
    return bg, bars, markers


def fire_marker_rays(grid, endpoint=4):
    """Bars fire rays perpendicular to themselves toward each marker, plus a
    "shadow" ray at each marker's position offset by the distance between the
    bars' starts (only where it lands within the bar's span).  Rays use the
    marker's color, stop before bars/markers, and markers become `endpoint`."""
    bg, bars, markers = find_structures(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    mcol = markers[0][2] if markers else bg

    def cells_of(b):
        if b['orient'] == 'V':
            return [(i, b['fixed']) for i in range(b['span'][0], b['span'][1] + 1)]
        return [(b['fixed'], j) for j in range(b['span'][0], b['span'][1] + 1)]

    barcells = {(r, c) for b in bars for r, c in cells_of(b)}
    mset = {(r, c) for r, c, _ in markers}
    for b in bars:
        axis = 'row' if b['orient'] == 'V' else 'col'
        lo, hi = b['span']
        fire = {}
        for m in markers:
            mc = m[0] if axis == 'row' else m[1]
            if lo <= mc <= hi:
                fire.setdefault(mc, m)
            for o in bars:
                if o is b:
                    continue
                c2 = mc - (o['span'][0] - b['span'][0])
                if lo <= c2 <= hi:
                    fire.setdefault(c2, m)
        for coord, m in fire.items():
            perp = m[1] if b['orient'] == 'V' else m[0]
            step = 1 if perp > b['fixed'] else -1
            pos = b['fixed'] + step
            limit = w if b['orient'] == 'V' else h
            while 0 <= pos < limit:
                cell = (coord, pos) if b['orient'] == 'V' else (pos, coord)
                if cell in barcells or cell in mset:
                    break
                out[cell[0]][cell[1]] = mcol
                pos += step
    for r, c, col in markers:
        out[r][c] = endpoint
    return out
